const $=id=>document.getElementById(id);let state={busy:false,can_install:false,can_restore:false},api=null;
function render(s){state=s;if(s.config){$('game').textContent=s.config.game;$('platform').textContent=s.config.platform;$('support').textContent='지원 게임 '+s.config.supported_game+' · 빌드 '+s.config.version_code+' · Quest 단독판';$('edition').textContent=s.config.publication;$('bundle').textContent='이 파일의 패치 v'+s.release+' · 게임 업데이트 후에는 새 패치가 필요합니다.';} for(const [id,key] of [['current','current'],['current-note','current_note'],['latest','latest'],['latest-note','latest_note'],['message','message'],['current-tag','tag']])if(s[key]!==undefined)$(id).textContent=s[key];$('current-tag').className='badge '+(s.tone||'neutral');$('current').className='version '+(s.tone||'neutral');$('latest').className='version '+(s.latest_tone||'neutral');$('install').disabled=s.busy||(!s.can_install&&!s.newer_release);$('restore').disabled=s.busy||!s.can_restore;$('retry').disabled=s.busy;$('install-text').textContent=s.newer_release?'최신 설치본 받기':(s.install_label||'한글패치 설치');$('progress').hidden=!s.busy;if(typeof s.percent==='number'){$('progress').max=100;$('progress').value=s.percent}else $('progress').removeAttribute('value');$('device-picker').hidden=!(s.devices&&s.devices.length>1);if(s.devices&&JSON.stringify(s.devices)!==$('device').dataset.items){$('device').dataset.items=JSON.stringify(s.devices);$('device').replaceChildren(new Option('기기를 선택해 주세요',''),...s.devices.map(x=>new Option(x,x)));} }
window.render=render;
async function call(name,...args){if(!api)return;try{const s=await api[name](...args);if(s)render(s)}catch(e){$('message').textContent='작업을 완료하지 못했습니다. 다시 확인해 주세요.'}}
function modal(title,text,accept='확인',cancel=true,terms=false){return new Promise(resolve=>{$('dialog-title').textContent=title;$('dialog-text').textContent=text;$('accept').textContent=accept;$('cancel').hidden=!cancel;$('terms').hidden=!terms;$('dialog').showModal();const finish=v=>{$('dialog').close();resolve(v)};$('accept').onclick=()=>finish(true);$('cancel').onclick=()=>finish(false);$('dialog').oncancel=e=>{e.preventDefault();finish(false)}})}
$('retry').onclick=()=>call('refresh');$('device').onchange=()=>call('select_device',$('device').value);
$('install').onclick=async()=>{if(state.newer_release){call('open_link','latest');return;}if(state.needs_terms&&!(await modal('Quest 연결 도구 준비','ADB가 없어 Google 공식 서버에서 다운로드합니다. Google Android SDK 약관에 동의하시면 계속 진행합니다.','동의하고 계속',true,true)))return;call('start','install',Boolean(state.needs_terms))};
$('restore').onclick=async()=>{if(await modal('한글패치를 제거할까요?','보관된 원본으로 게임 파일을 복구합니다. 세이브 진행 상황은 유지됩니다.','원본 복구'))call('start','restore',false)};
$('help').onclick=()=>modal('설치 · 복구 안내',
'1. Quest의 개발자 모드를 켜고 USB로 연결합니다.\n2. 헤드셋에서 USB 디버깅을 허용합니다.\n3. 게임을 완전히 종료한 뒤 설치 버튼을 누릅니다.\n\n제거할 때는 이 EXE를 다시 실행하고 “제거 · 원본 복구”를 누르세요. EXE를 옮겨도 백업과 설치 기록은 유지됩니다.\n\n필수: Windows 10/11 64비트 · WebView2 · .NET 4.8\n여유 공간: PC 약 9 GiB / Quest 4.2 GiB\nADB 최초 준비·최신 버전 확인은 인터넷 필요\n\n백업 보관 위치:\n'+(state.backup_path||'아래 백업 폴더 열기 버튼으로 확인해 주세요.')+'\n\n지원 게임: Quest 단독판 '+state.config.supported_game+' ('+state.config.version_code+')\n게임 버전이 바뀌면 새 패치가 나올 때까지 사용할 수 없습니다.','닫기',false);
document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>call('open_link',b.dataset.link));
window.addEventListener('pywebviewready',()=>{api=window.pywebview.api;call('refresh');setInterval(()=>call('get_state'),750)});

document.getElementById('backup-folder').onclick=()=>call('open_link','backup');
document.getElementById('license-folder').onclick=()=>call('open_link','licenses');
